	public virtual bool OnBeforeDrawDicePhaseEffects()
	{
		List<bool> list = new List<bool>();
		list.Add(IsEffectActiveRemoveEffect(effectsList.IncorruptibleEffect));
		if (ReferenceSingleton<AssetsReference>.Instance.PlayerRunStats.CurrentBattle.BattleTurnCounter > 1)
		{
			list.Add(IsEffectActiveAndDecreaseEffect(effectsList.BarrierEffect, 1));
			list.Add(RemoveLightShield());
		}
		list.Add(IsEffectActiveWithActivation(effectsList.SafeguardEffect));
		list.Add(IsEffectActiveWithActivation(effectsList.DisorderedNextTurnEffect));
		return list.Contains(item: true);
	}

	public virtual bool RemoveLightShield()
	{
		List<bool> list = new List<bool>();
		bool num = !(this is PlayerEffects);
		bool flag = false;
		if (num && IsEffectActiveAndDecreaseEffect(effectsList.FortifyEffect, 1))
		{
			flag = true;
		}
		if (!flag)
		{
			list.Add(IsEffectActiveRemoveEffect(effectsList.LightShieldEffect));
		}
		return list.Contains(item: true);
	}

