	public virtual void AddEffect(Effect effect, int effectAmount, bool effectFeedback = true, bool callEffectsCallbacks = true, GameObject source = null, bool gainingEffectVFXAndSFX = true, int renderLayer = -1, bool ignoreNegatableByEffectEnum = false)
	{
		if (GameScenesUtils.IsBattleScene())
		{
			CheckEffectsBeforeBloodySolstice();
			effectAmount = CheckBloodySolsticeEffect(effectAmount);
			if (effect == effectsList.LightShieldEffect)
			{
				effectAmount -= ReferenceSingleton<AssetsReference>.Instance.CurrentActiveUnits.IsDarknessAuraEffectActiveGetAmount();
				if (effectAmount <= 0)
				{
					return;
				}
			}
			if (!ignoreNegatableByEffectEnum)
			{
				if (effect.NegatableByEffectEnum == ProtectionHollowSkinEnum.PROTECTION)
				{
					if (IsEffectActiveWithActivation(effectsList.ProtectionEffect))
					{
						return;
					}
				}
				else if (effect.NegatableByEffectEnum == ProtectionHollowSkinEnum.HOLLOWSKIN && IsEffectActiveWithActivation(effectsList.HollowSkinEffect))
				{
					return;
				}
			}
		}
		EffectInstance effectInstance = IsEffectActiveGetEffectInstance(effect);
		if (effectInstance != null)
		{
			bool flag = effectAmount == EffectsValues.NO_VALUE;
			IncreaseEffect(effectInstance, effectAmount, source, !flag && effectFeedback, callEffectsCallbacks, gainingEffectVFXAndSFX);
		}
		else
		{
			effectInstance = ReferenceSingleton<PoolHandler>.Instance.GetObject(effectInstancePrefab.name, effectsHolder).GetComponent<EffectInstance>();
			activeEffectsList.Add(effectInstance);
			CheckEffectInstancesAmountAdjustSizes();
			if (effectFeedback)
			{
				unitFeedbackHandler.EnqueueEffectFeedbackAndPlay(effect, effectAmount, gainingEffectVFXAndSFX, playInstantSFX: true);
			}
			effectInstance.Initialize(effect, effectAmount, base.gameObject, source, effectFeedback, callEffectsCallbacks, gainingEffectVFXAndSFX, renderLayer);
		}
		if (GameScenesUtils.IsBattleScene())
		{
			if (effect == effectsList.LightShieldEffect)
			{
				ReferenceSingleton<MiscOmensHandler>.Instance.ShieldedCrossbowOmenAction?.Invoke(effectAmount, base.gameObject);
			}
			else if (effect == effectsList.EmpowerEffect)
			{
				ReferenceSingleton<CellariusOmensHandler>.Instance.WaterSwordOmenAction?.Invoke(effectAmount, base.gameObject);
			}
		}
		int CheckBloodySolsticeEffect(int _effectAmount)
		{
			BattleHandler instance = ReferenceSingleton<BattleHandler>.Instance;
			if (instance.IsSourcePlayer(source) && effect.NegatableByEffectEnum == ProtectionHollowSkinEnum.HOLLOWSKIN && instance.PlayerGameObject.GetComponent<PlayerEffects>().IsPlayerBloodySolstice())
			{
				if (!(this is PlayerEffects))
				{
					return _effectAmount *= 2;
				}
				PlayerEffects playerEffects = this as PlayerEffects;
				if (effect != playerEffects.PlayerEffectsList.BloodySolsticeNextTurnEffect && effect != playerEffects.PlayerEffectsList.BloodySolsticeActiveEffect)
				{
					return _effectAmount *= 2;
				}
			}
			return _effectAmount;
		}
		void CheckEffectsBeforeBloodySolstice()
		{
			if (effect == effectsList.LightShieldEffect)
			{
				if (ReferenceSingleton<MiscOmensHandler>.Instance.SleepyPillowOmenAction != null)
				{
					effectAmount = ReferenceSingleton<MiscOmensHandler>.Instance.SleepyPillowOmenAction(effectAmount);
				}
			}
			else if (effect == effectsList.ReliefEffect)
			{
				if (ReferenceSingleton<SothisOmensHandler>.Instance.TaintedKhepreshReliefOmenAction != null)
				{
					effectAmount = ReferenceSingleton<SothisOmensHandler>.Instance.TaintedKhepreshReliefOmenAction(effectAmount);
				}
			}
			else if (effect == effectsList.EmpowerEffect && ReferenceSingleton<CellariusOmensHandler>.Instance.SapphireFishingRodOmenAction != null)
			{
				effectAmount = ReferenceSingleton<CellariusOmensHandler>.Instance.SapphireFishingRodOmenAction(effectAmount);
			}
		}
	}

	private void CheckEffectInstancesAmountAdjustSizes()
	{
		if (activeEffectsList.Count <= 8)
		{
			gridLayoutGroup.cellSize = Vector2.one * 53f;
			gridLayoutGroup.spacing = new Vector2(0f, -4f);
			gridLayoutGroup.padding.top = 5;
		}
		else if (activeEffectsList.Count <= 10)
		{
			gridLayoutGroup.cellSize = Vector2.one * 48f;
			gridLayoutGroup.spacing = new Vector2(2f, -2f);
			gridLayoutGroup.padding.top = 3;
		}
		else if (activeEffectsList.Count == 11)
		{
			gridLayoutGroup.cellSize = Vector2.one * 38f;
			gridLayoutGroup.spacing = new Vector2(3f, 4f);
			gridLayoutGroup.padding.top = -2;
		}
	}

