	private void IncreaseEffect(EffectInstance effectInstance, int amount, GameObject source, bool effectFeedback, bool callEffectsCallbacks, bool gainingEffectVFXAndSFX)
	{
		if (effectFeedback)
		{
			unitFeedbackHandler.EnqueueIncreaseDecreaseEffectFeedbackAndPlay(effectInstance.Effect, amount, gainingEffectVFXAndSFX);
		}
		effectInstance.IncreaseEffect(amount, source, callEffectsCallbacks, gainingEffectVFXAndSFX);
	}

	public void DecreaseEffect(Effect effect, int amount, bool activateFeedback = true)
	{
		if (amount == 0)
		{
			Debug.Log("UNIT EFFECT " + base.gameObject.name + ": Trying to decrease effect: " + effect.name + " by 0", base.gameObject);
			return;
		}
		EffectInstance effectInstance = IsEffectActiveGetEffectInstance(effect);
		if (effectInstance != null)
		{
			DecreaseEffect(effectInstance, amount, activateFeedback);
			return;
		}
		Debug.Log("UNIT EFFECT " + base.gameObject.name + ": Effect instance null, trying to decrease effect " + effect.name + " by " + amount, base.gameObject);
	}

	public void DecreaseEffect(EffectInstance effectInstance, int amount, bool activateFeedback = true, bool removeOnZero = true)
	{
		if (effectInstance.EffectAmount < EffectsValues.INFINITY)
		{
			if ((effectInstance.EffectAmount - amount > 0 && activateFeedback) || (!removeOnZero && activateFeedback))
			{
				unitFeedbackHandler.EnqueueIncreaseDecreaseEffectFeedbackAndPlay(effectInstance.Effect, -amount, gainingEffectVFXAndSFX: false);
				effectInstance.DecreaseEffect(amount, activateFeedback, removeOnZero);
			}
			else
			{
				effectInstance.DecreaseEffect(amount, activateFeedback, removeOnZero);
			}
		}
	}

	public void RemoveEffect(EffectInstance effectInstance, bool activateFeedback = true)
	{
		if (activeEffectsList.Contains(effectInstance))
		{
			if (activateFeedback)
			{
				RemoveEffect(effectInstance);
				unitFeedbackHandler.EnqueueRemoveEffectFeedbackAndPlay(effectInstance.Effect, effectInstance.EffectAmount);
			}
			else
			{
				RemoveEffect(effectInstance);
			}
		}
	}

	private void RemoveEffect(EffectInstance effectInstance)
	{
		ReferenceSingleton<PoolHandler>.Instance.StoreObject(effectInstance.gameObject);
		activeEffectsList.Remove(effectInstance);
		CheckEffectInstancesAmountAdjustSizes();
		effectInstance.Effect.RemoveEffect(effectInstance.EffectAmount, base.gameObject);
	}

	protected void RemoveEffectWithoutCallbacks(EffectInstance effectInstance)
	{
		ReferenceSingleton<PoolHandler>.Instance.StoreObject(effectInstance.gameObject);
		activeEffectsList.Remove(effectInstance);
		CheckEffectInstancesAmountAdjustSizes();
	}

	public void RemoveEffect(Effect effect, bool activateFeedback = true)
	{
		EffectInstance effectInstance = IsEffectActiveGetEffectInstance(effect);
		if (effectInstance != null)
		{
			RemoveEffect(effectInstance, activateFeedback);
		}
	}

	public void RemoveAllEffectsWithCallbacks()
	{
		for (int num = activeEffectsList.Count - 1; num >= 0; num--)
		{
			RemoveEffect(activeEffectsList[num]);
		}
	}

