	public void RemoveAllEffectWithoutCallbacks()
	{
		for (int num = activeEffectsList.Count - 1; num >= 0; num--)
		{
			EffectInstance effectInstance = activeEffectsList[num];
			RemoveEffectWithoutCallbacks(effectInstance);
		}
	}

	public EffectInstance IsEffectActiveGetEffectInstance(Effect effect)
	{
		for (int i = 0; i < activeEffectsList.Count; i++)
		{
			if (activeEffectsList[i].Effect == effect)
			{
				return activeEffectsList[i];
			}
		}
		return null;
	}

	public bool IsEffectActive(Effect effect, bool activateFeedback = true, bool enqueueFeedback = true)
	{
		for (int i = 0; i < activeEffectsList.Count; i++)
		{
			if (!(activeEffectsList[i].Effect == effect))
			{
				continue;
			}
			if (activateFeedback)
			{
				if (enqueueFeedback)
				{
					unitFeedbackHandler.EnqueueEffectFeedbackAndPlay(effect);
				}
				else
				{
					unitFeedbackHandler.PlayFeedbackNotEnqueuing(effect);
				}
			}
			return true;
		}
		return false;
	}

	public bool IsEffectActiveWithActivation(Effect effect, bool activateFeedback = true, bool updateAmount = true)
	{
		for (int i = 0; i < activeEffectsList.Count; i++)
		{
			if (activeEffectsList[i] == null)
			{
				Debug.Log("-------------IsEffectActiveWithActivation activeEffectsList[i] IS NULL-------------");
			}
			if (activeEffectsList[i].Effect == effect)
			{
				if (activateFeedback)
				{
					unitFeedbackHandler.EnqueueEffectFeedbackAndPlay(effect);
				}
				activeEffectsList[i].ActivateEffect(updateAmount);
				return true;
			}
		}
		return false;
	}

