		for (int i = 0; i < activeEffectsList.Count; i++)
		{
			if (activeEffectsList[i].Effect == effect)
			{
				DecreaseEffect(activeEffectsList[i], amount, activateFeedback, removeOnZero);
				return true;
			}
		}
		return false;
