	public bool IsEffectActiveAndDecreaseEffectByHalf(Effect effect, bool activateFeedback = true, bool removeOnZero = true)
	{
		for (int i = 0; i < activeEffectsList.Count; i++)
		{
			if (activeEffectsList[i].Effect == effect)
			{
				int amount = Mathf.CeilToInt((float)activeEffectsList[i].EffectAmount / 2f);
				DecreaseEffect(activeEffectsList[i], amount, activateFeedback, removeOnZero);
				return true;
			}
		}
		return false;
	}

	public int IsEffectActiveGetAmountAndDecreaseEffect(Effect effect, int amount, bool activateFeedback = true)
